<script lang="ts">
  import { onMount } from 'svelte'; import CheckCircle2 from 'lucide-svelte/icons/circle-check-big'; import CircleDashed from 'lucide-svelte/icons/circle-dashed'; import ExternalLink from 'lucide-svelte/icons/external-link'; import ServerCog from 'lucide-svelte/icons/server-cog';
  import PageHeader from '$lib/components/PageHeader.svelte'; import AsyncState from '$lib/components/AsyncState.svelte'; import StatusBadge from '$lib/components/StatusBadge.svelte'; import { api, shortDate } from '$lib/api/client';
  let data = $state<any>(null); let loading = $state(true); let error = $state('');
  onMount(async () => { try { data = await api('/health/integrations'); } catch (cause) { error = cause instanceof Error ? cause.message : String(cause); } finally { loading = false; } });
</script>
<PageHeader eyebrow="Operational readiness" title="Integrations" description="Configuration and health are reported without exposing secret values. Setup guidance follows the repository’s .env.example contract." />
<AsyncState {loading} {error}>{#if data}<div class="actions" style="margin-bottom:18px"><span class="badge" data-tone="info">{data.mode} mode</span><a class="btn btn-secondary" href="https://sandbox.api.prava.space/health" target="_blank" rel="noreferrer">Prava sandbox health <ExternalLink size={14} /></a></div><div class="grid grid-3">{#each data.integrations as item}<article class="card card-pad"><div style="display:flex;justify-content:space-between;gap:12px;align-items:start"><div class="brand-mark" style={`background:${item.healthy ? 'var(--mint-soft)' : '#eef0eb'};box-shadow:none`}>{#if item.healthy}<CheckCircle2 size={20} />{:else}<CircleDashed size={20} />{/if}</div><StatusBadge status={item.configured ? 'configured' : 'missing'} tone={item.configured ? 'success' : 'warning'} /></div><h2 style="margin:18px 0 5px;font-size:1rem">{item.name}</h2><p class="small muted" style="min-height:35px">{item.message}</p><div class="actions">{#each item.supported_modalities as modality}<span class="badge">{modality}</span>{/each}</div><div style="border-top:1px solid var(--line);margin-top:16px;padding-top:14px"><div class="small"><strong>Last successful check:</strong> {shortDate(item.last_success_at)}</div><p class="help"><ServerCog size={12} style="display:inline" /> {item.setup}</p></div></article>{/each}</div>{/if}</AsyncState>
